"""Internal HTTP client used by the CLI and local proxy runner."""

from __future__ import annotations

import asyncio
import json
import os
import webbrowser
from collections.abc import Mapping
from pathlib import Path
from typing import Any
from urllib.parse import urlparse

import requests

from authsome.identity import (
    IdentitySource,
    load_runtime_identity,
    mark_claimed,
    mark_registered,
)
from authsome.identity.local import RuntimeIdentity, load_identity
from authsome.identity.proof import POP_AUTH_SCHEME, create_proof_jwt
from authsome.server.urls import DEFAULT_SERVER_BASE_URL

DEFAULT_DAEMON_URL = DEFAULT_SERVER_BASE_URL
IDENTITY_OVERRIDE_ENV = "AUTHSOME_IDENTITY"


def resolve_daemon_url(env: Mapping[str, str] | None = None) -> str:
    """Return the configured daemon URL for CLI and proxy clients."""
    values = env if env is not None else os.environ
    raw = values.get("AUTHSOME_DAEMON_URL", DEFAULT_DAEMON_URL).strip()
    return raw.rstrip("/") or DEFAULT_DAEMON_URL


def is_local_daemon_url(url: str) -> bool:
    """Return whether the configured daemon URL targets a local loopback daemon."""
    hostname = urlparse(url).hostname
    return hostname in {"127.0.0.1", "localhost", "::1"}


def is_managed_local_daemon_url(url: str) -> bool:
    """Return whether the URL matches the default local daemon managed by the CLI."""
    parsed = urlparse(url)
    if parsed.scheme != "http":
        return False
    if parsed.path not in {"", "/"}:
        return False
    return parsed.hostname in {"127.0.0.1", "localhost", "::1"} and (parsed.port in {None, 7998})


def raise_for_error(response: requests.Response) -> None:
    try:
        response.raise_for_status()
    except requests.HTTPError as exc:
        obj = None
        try:
            data = response.json()
            error_name = data.get("error")
            message = data.get("message")
            if error_name and message:
                import authsome.errors as err_mod

                exc_cls = getattr(err_mod, error_name, None)
                if exc_cls and issubclass(exc_cls, err_mod.AuthsomeError):
                    obj = exc_cls.__new__(exc_cls)
                    Exception.__init__(obj, message)
                    obj.provider = data.get("provider")
                    obj.operation = data.get("operation")
        except Exception:
            pass

        if obj is not None:
            raise obj from exc

        raise exc


class AuthsomeApiClient:
    """Small typed wrapper around the daemon API."""

    def __init__(self, base_url: str | None = None) -> None:
        self._base_url = (base_url or resolve_daemon_url()).rstrip("/")
        self._home = Path(os.environ.get("AUTHSOME_HOME", str(Path.home() / ".authsome")))

    @property
    def base_url(self) -> str:
        return self._base_url

    async def _request(
        self,
        method: str,
        path: str,
        *,
        body: dict[str, Any] | None = None,
        timeout: int = 30,
        protected: bool = True,
    ) -> dict[str, Any]:
        body_bytes = b""
        headers: dict[str, str | bytes] = {}
        if body is not None:
            body_bytes = json.dumps(body, separators=(",", ":"), sort_keys=True).encode("utf-8")
            headers["Content-Type"] = "application/json"
        if protected:
            headers.update(await self._proof_headers(method, path, body_bytes))
        response = await asyncio.to_thread(
            requests.request,
            method,
            f"{self._base_url}{path}",
            data=body_bytes if body is not None else None,
            headers=headers,
            timeout=timeout,
        )
        raise_for_error(response)
        return response.json()

    def _runtime_identity(self) -> RuntimeIdentity:
        return load_runtime_identity(self._home)

    def _runtime_for_handle(self, handle: str) -> RuntimeIdentity:
        return load_runtime_identity(self._home, env={IDENTITY_OVERRIDE_ENV: handle})

    async def _proof_headers(self, method: str, path: str, body: bytes) -> dict[str, str | bytes]:
        identity = await self.ensure_identity_ready()
        token = create_proof_jwt(
            private_key=identity.signer,
            issuer=identity.did,
            subject=identity.handle,
            method=method,
            path_query=path,
            body=body,
        )
        return {"Authorization": f"{POP_AUTH_SCHEME} {token}"}

    async def ensure_identity_ready(self) -> RuntimeIdentity:
        """Ensure the acting identity is registered and, in hosted mode, claimed."""
        runtime = self._runtime_identity()
        if runtime.source is IdentitySource.ENV:
            return await self._ensure_env_identity_ready(runtime)

        status: dict[str, Any] | None = None
        identity = load_identity(self._home, runtime.handle)
        if not identity.registered:
            status = await self.register_identity(identity.handle, identity.did)
            identity = mark_registered(self._home, identity.handle)
        elif identity.claimed:
            return runtime
        else:
            try:
                status = await self.get_identity_status(identity.handle)
            except Exception:
                status = await self.register_identity(identity.handle, identity.did)

        registration_status = status.get("registration_status", "registered") if status else "registered"
        if registration_status == "claim_required":
            claim_url = status.get("claim_url")
            if not claim_url:
                status = await self.register_identity(identity.handle, identity.did)
                claim_url = status.get("claim_url")
            if claim_url:
                try:
                    webbrowser.open(claim_url)
                except Exception:
                    pass
            await self._poll_claim_completion(identity.handle)
            identity = mark_claimed(self._home, identity.handle)
            return self._runtime_for_handle(identity.handle)

        if registration_status in {"claimed", "registered"}:
            identity = mark_claimed(self._home, identity.handle)
            return self._runtime_for_handle(identity.handle)

        return self._runtime_for_handle(identity.handle)

    async def _ensure_env_identity_ready(self, identity: RuntimeIdentity) -> RuntimeIdentity:
        try:
            status = await self.get_identity_status(identity.handle)
        except Exception:
            status = await self.register_identity(identity.handle, identity.did)

        registration_status = status.get("registration_status", "registered")
        if registration_status == "claim_required":
            claim_url = status.get("claim_url")
            if not claim_url:
                status = await self.register_identity(identity.handle, identity.did)
                claim_url = status.get("claim_url")
            if claim_url:
                try:
                    webbrowser.open(claim_url)
                except Exception:
                    pass
            await self._poll_claim_completion(identity.handle)
        return identity

    async def _poll_claim_completion(self, handle: str, *, timeout_seconds: int = 300) -> dict[str, Any]:
        deadline = asyncio.get_running_loop().time() + timeout_seconds
        while True:
            status = await self.get_identity_status(handle)
            if status.get("registration_status") in {"claimed", "registered"}:
                return status
            if asyncio.get_running_loop().time() >= deadline:
                raise TimeoutError(f"Timed out waiting for identity '{handle}' to be claimed")
            await asyncio.sleep(1)

    async def _get(self, path: str, *, protected: bool = True) -> dict[str, Any]:
        return await self._request("GET", path, timeout=10, protected=protected)

    async def _post(self, path: str, body: dict[str, Any] | None = None, *, protected: bool = True) -> dict[str, Any]:
        return await self._request("POST", path, body=body or {}, timeout=30, protected=protected)

    async def _delete(self, path: str, *, protected: bool = True) -> dict[str, Any]:
        return await self._request("DELETE", path, timeout=30, protected=protected)

    async def health(self) -> dict[str, Any]:
        return await self._get("/health", protected=False)

    async def ready(self) -> dict[str, Any]:
        return await self._get("/ready")

    async def start_login(self, **kwargs: Any) -> dict[str, Any]:
        return await self._post("/auth/sessions", kwargs)

    async def get_session(self, session_id: str) -> dict[str, Any]:
        return await self._get(f"/auth/sessions/{session_id}")

    async def resume_login_session(self, session_id: str, **kwargs: Any) -> dict[str, Any]:
        return await self._post(f"/auth/sessions/{session_id}/resume", {"data": kwargs})

    async def list_connections(self) -> dict[str, Any]:
        return await self._get("/connections")

    async def get_connection(self, provider: str, connection_name: str = "default") -> dict[str, Any]:
        return await self._get(f"/connections/{provider}/{connection_name}")

    async def logout(self, provider: str, connection_name: str = "default") -> None:
        await self._post(f"/connections/{provider}/{connection_name}/logout")

    async def revoke(self, provider: str) -> None:
        await self._post(f"/connections/{provider}/revoke")

    async def set_default_connection(self, provider: str, connection_name: str) -> None:
        await self._post(f"/connections/{provider}/{connection_name}/default")

    async def get_provider(self, provider: str) -> dict[str, Any]:
        return await self._get(f"/providers/{provider}")

    async def register_provider(self, definition_dict: dict[str, Any], force: bool = False) -> None:
        await self._post("/providers", {"definition": definition_dict, "force": force})

    async def register_identity(self, handle: str, did: str) -> dict[str, Any]:
        return await self._post("/identities/register", {"handle": handle, "did": did}, protected=False)

    async def get_identity_status(self, handle: str) -> dict[str, Any]:
        return await self._get(f"/identities/{handle}", protected=False)

    async def remove(self, provider: str) -> None:
        await self._delete(f"/providers/{provider}")

    async def list_providers_by_source(self) -> dict[str, Any]:
        return await self._get("/providers")

    async def export(self, provider: str | None = None, connection_name: str = "default", format: str = "env") -> str:
        result = await self._post(
            "/credentials/export",
            {"provider": provider, "connection": connection_name, "format": format},
        )
        return result["output"]

    async def proxy_routes(self, scope: str = "connected") -> dict[str, Any]:
        """Return proxy routes from a PoP-protected daemon endpoint.

        The scope is owned by the caller (read from `ClientConfig.proxy_mode`);
        the daemon merely projects its connections/providers into the
        requested view.
        """
        return await self._get(f"/proxy/routes?scope={scope}")

    async def resolve_credentials(self, **kwargs: Any) -> dict[str, Any]:
        """Resolve proxy credentials from a PoP-protected daemon endpoint."""
        return await self._post("/credentials/resolve", kwargs)

    async def whoami(self) -> dict[str, Any]:
        return await self._get("/whoami")

    async def doctor(self) -> dict[str, Any]:
        return await self.ready()

    async def start_ui_session(self) -> dict[str, Any]:
        return await self._post("/ui/session")

"""Administrative CLI commands for authsome."""

import json as json_lib
import os
import sys
from pathlib import Path

import click

from authsome.cli.context import ContextObj
from authsome.cli.daemon_control import (
    DaemonAlreadyRunningError,
    DaemonUnavailableError,
    daemon_status,
    is_daemon_responsive,
    is_port_occupied,
    start_daemon,
    stop_daemon,
    wait_for_daemon_ready,
)
from authsome.cli.helpers import auth_command
from authsome.paths import get_client_log_path, get_server_log_path


@click.group(name="admin")
def admin() -> None:
    """Manage operator-facing daemon and maintenance commands."""


@admin.command(name="log")
@click.option("-n", "--lines", default=50, metavar="COUNT", help="Number of entries to show.")
@click.option("--raw", is_flag=True, help="Show raw client debug log instead of structured audit entries.")
@auth_command
async def log_cmd(ctx_obj: ContextObj, lines: int, raw: bool) -> None:
    """View structured audit entries or the raw client debug log."""
    home = Path(os.environ.get("AUTHSOME_HOME", str(Path.home() / ".authsome")))

    if raw:
        log_path = get_client_log_path(home)
        try:
            raw_lines = log_path.read_text(encoding="utf-8", errors="replace").splitlines()[-lines:]
        except FileNotFoundError:
            raw_lines = []
        ctx_obj.print_json({"log_file": str(log_path), "entries": raw_lines})
        return

    audit_path = get_server_log_path(home)
    try:
        raw_lines = audit_path.read_text(encoding="utf-8", errors="replace").splitlines()[-lines:]
    except FileNotFoundError:
        raw_lines = []

    parsed: list[dict] = []
    for line in raw_lines:
        line = line.strip()
        if not line:
            continue
        try:
            parsed.append(json_lib.loads(line))
        except Exception:
            parsed.append({"raw": line})

    ctx_obj.print_json({"log_file": str(audit_path), "entries": parsed})


@admin.group(name="daemon")
def daemon() -> None:
    """Manage the local Authsome daemon."""


@daemon.command(name="serve")
@click.option("--host", default="127.0.0.1", show_default=True, metavar="HOST", help="Host interface to bind.")
@click.option("--port", default=7998, type=int, show_default=True, metavar="PORT", help="TCP port to listen on.")
@click.option("--reload", is_flag=True, help="Enable auto-reload on code changes.")
def daemon_serve(host: str, port: int, reload: bool) -> None:
    """Run the daemon in the foreground."""
    from authsome.server.daemon import serve

    serve(host=host, port=port, reload=reload)


@daemon.command(name="start")
@auth_command
async def daemon_start(ctx_obj: ContextObj) -> None:
    """Start the local daemon in the background."""
    if await is_daemon_responsive():
        ctx_obj.print_json({"status": "already_running", "message": "Daemon is already running."})
        return

    if is_port_occupied(7998):
        ctx_obj.print_json(
            {
                "status": "port_occupied",
                "message": "Port 7998 is occupied by an unrelated process. We did not start a new process.",
            }
        )
        return

    try:
        start_daemon()
        await wait_for_daemon_ready(timeout=5)
        ctx_obj.print_json({"status": "started", "message": "Daemon started successfully."})
    except DaemonAlreadyRunningError as exc:
        pid_str = f" (PID: {exc.pid})" if exc.pid else ""
        ctx_obj.print_json({"status": "already_running", "message": f"Daemon is already running{pid_str}."})
    except DaemonUnavailableError as exc:
        ctx_obj.print_json({"error": exc.__class__.__name__, "message": str(exc)})
        sys.exit(1)


@daemon.command(name="stop")
@auth_command
async def daemon_stop(ctx_obj: ContextObj) -> None:
    """Stop the local daemon."""
    stopped, message = await stop_daemon()
    status = "stopped" if stopped else "not_stopped"
    ctx_obj.print_json({"status": status, "message": message})


@daemon.command(name="restart")
@auth_command
async def daemon_restart(ctx_obj: ContextObj) -> None:
    """Restart the local daemon."""
    stopped, message = await stop_daemon()

    if await is_daemon_responsive():
        ctx_obj.print_json(
            {
                "status": "already_running",
                "message": "Daemon is already running on port 7998. We did not start a new process.",
                "stop_message": message,
                "stopped": stopped,
            }
        )
        return

    if is_port_occupied(7998):
        ctx_obj.print_json(
            {
                "status": "port_occupied",
                "message": "Port 7998 is occupied by an unrelated process. We did not start a new process.",
                "stop_message": message,
                "stopped": stopped,
            }
        )
        return

    try:
        start_daemon()
        await wait_for_daemon_ready(timeout=5)
        ctx_obj.print_json(
            {
                "status": "restarted" if stopped else "started",
                "message": "Daemon restarted successfully." if stopped else "New daemon started.",
                "stop_message": message,
                "stopped": stopped,
            }
        )
    except DaemonAlreadyRunningError as exc:
        pid_str = f" (PID: {exc.pid})" if exc.pid else ""
        ctx_obj.print_json(
            {
                "status": "already_running",
                "message": f"Daemon is already running{pid_str}.",
                "stop_message": message,
                "stopped": stopped,
            }
        )
    except DaemonUnavailableError as exc:
        ctx_obj.print_json({"error": exc.__class__.__name__, "message": str(exc)})
        sys.exit(1)


@daemon.command(name="status")
@auth_command
async def daemon_status_cmd(ctx_obj: ContextObj) -> None:
    """Show daemon status."""
    status = await daemon_status()
    ctx_obj.print_json(status)


@daemon.command(name="logs")
@click.option("-n", "--lines", default=80, metavar="COUNT", help="Number of lines to show.")
@auth_command
async def daemon_logs(ctx_obj: ContextObj, lines: int) -> None:
    """Show daemon log output."""
    from authsome.cli.daemon_control import LOG_FILE

    if not LOG_FILE.exists():
        ctx_obj.print_json({"log_file": str(LOG_FILE), "entries": []})
        return
    entries = LOG_FILE.read_text(encoding="utf-8", errors="replace").splitlines()[-lines:]
    ctx_obj.print_json({"log_file": str(LOG_FILE), "entries": entries})

"""Local daemon process control for CLI commands."""

from __future__ import annotations

import asyncio
import json
import os
import signal
import subprocess
import sys
import time
from typing import Any

from authsome.cli.client import (
    DEFAULT_DAEMON_URL,
    AuthsomeApiClient,
    is_managed_local_daemon_url,
    resolve_daemon_url,
)
from authsome.paths import get_authsome_home, get_server_home
from authsome.server.daemon import DEFAULT_HOST, DEFAULT_PORT

AUTHSOME_HOME = get_authsome_home()
DAEMON_DIR = get_server_home(AUTHSOME_HOME) / "daemon"
PID_FILE = DAEMON_DIR / "daemon.pid"
LOG_FILE = DAEMON_DIR / "daemon.log"
STATE_FILE = DAEMON_DIR / "daemon.json"


class DaemonUnavailableError(RuntimeError):
    """Raised when the local daemon cannot be started or reached."""


async def is_daemon_responsive() -> bool:
    """Return whether the daemon is currently responsive on the default loopback port."""
    client = AuthsomeApiClient(DEFAULT_DAEMON_URL)
    return await _is_ready(client)


def is_port_occupied(port: int = 7998) -> bool:
    """Return whether the port is currently occupied by any listening process."""
    import socket

    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
        s.settimeout(0.2)
        try:
            s.connect(("127.0.0.1", port))
            return True
        except Exception:
            return False


class DaemonAlreadyRunningError(RuntimeError):
    """Raised when the daemon is already running."""

    def __init__(self, pid: int | None = None) -> None:
        super().__init__("Daemon is already running.")
        self.pid = pid


async def ensure_daemon() -> AuthsomeApiClient:
    """Return a ready daemon client, starting/restarting the daemon if needed."""
    client = AuthsomeApiClient(DEFAULT_DAEMON_URL)
    if await _is_ready(client):
        return client
    await stop_daemon()
    start_daemon()
    await wait_for_daemon_ready()
    return client


async def wait_for_daemon_ready(timeout: int = 10) -> None:
    """Wait for the daemon to become ready, raising an error if it fails."""
    client = AuthsomeApiClient(DEFAULT_DAEMON_URL)
    deadline = time.monotonic() + timeout
    while time.monotonic() < deadline:
        if await _is_ready(client):
            return
        # If the process died, fail fast instead of waiting for timeout
        pid = _read_pid()
        if pid is not None and not _process_alive(pid):
            break
        await asyncio.sleep(0.2)
    raise DaemonUnavailableError(_startup_error())


async def resolve_runtime_client() -> AuthsomeApiClient:
    """Return the configured runtime client, auto-starting only for local mode."""
    client = AuthsomeApiClient(resolve_daemon_url())
    if is_managed_local_daemon_url(client.base_url):
        return await ensure_daemon()
    return client


def start_daemon() -> None:
    if _pid_file_process_alive():
        raise DaemonAlreadyRunningError(_read_pid())

    DAEMON_DIR.mkdir(parents=True, exist_ok=True)
    log = LOG_FILE.open("ab")
    process = subprocess.Popen(
        [sys.executable, "-m", "authsome.cli.main", "admin", "daemon", "serve"],
        stdout=log,
        stderr=log,
        start_new_session=True,
    )
    PID_FILE.write_text(str(process.pid), encoding="utf-8")
    STATE_FILE.write_text(
        json.dumps({"pid": process.pid, "host": DEFAULT_HOST, "port": DEFAULT_PORT}, indent=2),
        encoding="utf-8",
    )


async def stop_daemon() -> tuple[bool, str]:
    """Stop the daemon process cleanly.

    Returns:
        (stopped, message)
    """
    pid = _read_pid()
    if pid is None:
        return False, "No managed daemon record was found, so no process was stopped."

    if not _process_alive(pid):
        _clear_daemon_files()
        return False, f"No running daemon process (PID: {pid}) was found to stop."

    try:
        os.kill(pid, signal.SIGTERM)
    except ProcessLookupError:
        _clear_daemon_files()
        return True, "Daemon process was already stopping."

    deadline = time.monotonic() + 5
    while time.monotonic() < deadline:
        if not _process_alive(pid):
            _clear_daemon_files()
            return True, "Daemon stopped successfully."
        await asyncio.sleep(0.2)

    try:
        os.kill(pid, signal.SIGKILL)
    except ProcessLookupError:
        pass

    _clear_daemon_files()
    if _process_alive(pid):
        return False, f"Failed to stop the daemon (PID: {pid}). The process is still lingering."
    return True, "Daemon stopped successfully (forcefully)."


async def daemon_status() -> dict[str, Any]:
    client = AuthsomeApiClient(DEFAULT_DAEMON_URL)
    try:
        health = await client.health()
        return {"running": True, "health": health, "pid_file": str(PID_FILE), "log_file": str(LOG_FILE)}
    except Exception as exc:
        return {"running": False, "error": str(exc), "pid_file": str(PID_FILE), "log_file": str(LOG_FILE)}


async def _is_ready(client: AuthsomeApiClient) -> bool:
    try:
        health = await client.health()
        from authsome import __version__

        if health.get("version") != __version__:
            return False

        return health.get("status") == "ok"
    except Exception:
        return False


def _read_pid() -> int | None:
    try:
        return int(PID_FILE.read_text(encoding="utf-8").strip())
    except Exception:
        return None


def _process_alive(pid: int) -> bool:
    try:
        os.kill(pid, 0)
        return True
    except OSError:
        return False


def _pid_file_process_alive() -> bool:
    pid = _read_pid()
    return pid is not None and _process_alive(pid)


def _clear_daemon_files() -> None:
    for path in (PID_FILE, STATE_FILE):
        try:
            path.unlink()
        except FileNotFoundError:
            pass


def _startup_error() -> str:
    lines: list[str] = []
    if LOG_FILE.exists():
        lines = LOG_FILE.read_text(encoding="utf-8", errors="replace").splitlines()[-12:]
    detail = "\n".join(lines) if lines else "No daemon log output was captured."
    return f"Authsome daemon failed to start.\nLog: {LOG_FILE}\n\n{detail}"

